"use strict";

export const FORTH_MANUAL_REF = "v2.0.1";

/** The groups, in the order the manual first uses them. */
export const FORTH_GROUPS = ["memory", "dictionary", "arithmetic", "control", "stack", "errors", "strings", "float", "I/O", "sound", "graphics", "printer", "storage"];

export const FORTH_WORD_ENTRIES = {
  "!": {"stack": "( x addr -- )", "kind": "word", "group": "memory", "desc": "Stores the cell x at addr: the low byte at addr, the high byte at addr+1. The address is not checked. A store into the ROM (addresses below 16,384) is ignored; anywhere else it overwrites whatever is there, the dictionary and the system variables included.", "example": "VARIABLE V\n1234 V !\nV @ .                      \\ expect: 1234\n258 V !  V C@ . V 1+ C@ .  \\ expect: 2 1", "part": "03_language.md"},
  "'": {"stack": "( \"name\" -- xt )", "kind": "word", "group": "dictionary", "desc": "Reads the next word from the line and leaves its execution token xt, the address of its code, without running it. EXECUTE runs an xt. Upper and lower case do not matter. It finds immediate words (' IF) as well as ordinary ones.", "example": ": SQ DUP * ;\n5 ' SQ EXECUTE .         \\ expect: 25\n' NOSUCH                 \\ expect: UNDEFINED WORD", "part": "03_language.md"},
  "(": {"stack": "( -- )", "kind": "immediate word", "group": "dictionary", "desc": "Starts a comment that ends at the next ). If there is no ) on the line, the rest of the line is the comment. It works at the prompt and inside a definition. Put a space after (: (x is not a comment.", "example": "1 ( the first ) 2 + .    \\ expect: 3\n: SHOW 5 ( a note ) . ;\nSHOW                     \\ expect: 5", "part": "03_language.md"},
  "*": {"stack": "( n1 n2 -- n3 )", "kind": "word", "group": "arithmetic", "desc": "Multiplies n1 by n2. Only the low 16 bits of the product are kept, so a product that does not fit wraps around, with no error.", "example": "6 7 * .                  \\ expect: 42\n-3 4 * .                 \\ expect: -12\n200 200 * .              \\ expect: -25536", "part": "03_language.md"},
  "+": {"stack": "( n1 n2 -- n3 )", "kind": "word", "group": "arithmetic", "desc": "Adds n1 and n2. The sum wraps around if it does not fit in a cell.", "example": "3 4 + .                  \\ expect: 7\n32767 1 + .              \\ expect: -32768", "part": "03_language.md"},
  "+LOOP": {"stack": "( step -- )", "kind": "compile-only word", "group": "control", "desc": "Closes a DO loop like LOOP, but adds step to the index instead of 1. Counting up, the loop ends when the index reaches or passes the limit. Counting down (a negative step), it ends when the index goes below the limit, so the last pass has the index equal to the limit. At run time +LOOP takes step from the stack.", "example": ": UP 10 0 DO I . 3 +LOOP ;\n: DOWN 0 10 DO I . -4 +LOOP ;\n: ZERO 0 10 DO I . -5 +LOOP ;\nUP                       \\ expect: 0 3 6 9\nDOWN                     \\ expect: 10 6 2\nZERO                     \\ expect: 10 5 0", "part": "03_language.md"},
  ",": {"stack": "( x -- )", "kind": "word", "group": "memory", "desc": "Compiles the cell x at HERE and moves HERE on by 2. The value is stored as it is, not as a literal. Use it after CREATE to fill a table.", "example": "CREATE TBL 10 , 20 , 30 ,\nTBL @ .                  \\ expect: 10\nTBL 2 CELLS + @ .        \\ expect: 30", "part": "03_language.md"},
  "-": {"stack": "( n1 n2 -- n3 )", "kind": "word", "group": "arithmetic", "desc": "Subtracts n2 from n1. The difference wraps around if it does not fit in a cell.", "example": "10 3 - .  3 10 - .       \\ expect: 7 -7\n-32768 1 - .             \\ expect: 32767", "part": "03_language.md"},
  ".": {"stack": "( n -- )", "kind": "word", "group": "I/O", "desc": "Prints n as a signed decimal number, with a minus sign if it is negative, followed by one space, at the print position. A cell is 16 bits, so a number above 32,767 that was meant as unsigned prints as a negative one: 65535 . prints -1.", "example": "42 .                     \\ expect: 42\n-7 .  0 .  32767 .       \\ expect: -7 0 32767\n65535 .                  \\ expect: -1", "part": "04_machine.md"},
  ".\"": {"stack": "( -- )", "kind": "compile-only word", "group": "I/O", "desc": "Used inside a definition: .\" text\" compiles the characters after the space that follows .\", up to the closing \", into the definition. When the definition runs, it prints them at the print position. There is no way to put a \" inside the text.", "example": ": HELLO .\" HELLO, WORLD\" CR ;\nHELLO                    \\ expect: HELLO, WORLD\n: AB .\" A\" .\" B\" ;\nAB                       \\ expect: AB", "part": "04_machine.md"},
  "/": {"stack": "( n1 n2 -- n3 )", "kind": "word", "group": "arithmetic", "desc": "Divides n1 by n2 and leaves the quotient n3, cut toward zero: -17 5 / is -3, not -4. The remainder is MOD's. Dividing by zero is not an error: the quotient is 0.", "example": "17 5 / .                 \\ expect: 3\n-17 5 / .  17 -5 / .     \\ expect: -3 -3\n17 0 / .                 \\ expect: 0", "part": "03_language.md"},
  "0=": {"stack": "( n -- flag )", "kind": "word", "group": "arithmetic", "desc": "Leaves -1 (true) if n is 0, and 0 (false) for any other number. Applied to a flag, it gives the opposite flag.", "example": "0 0= . 5 0= . -1 0= .    \\ expect: -1 0 0\n5 5 - 0= .               \\ expect: -1\n3 0= 0= .                \\ expect: -1", "part": "03_language.md"},
  "1+": {"stack": "( n1 -- n2 )", "kind": "word", "group": "arithmetic", "desc": "Adds 1 to n1. The same as 1 +, in one word. 32767 becomes -32768.", "example": "5 1+ .                   \\ expect: 6\n32767 1+ .               \\ expect: -32768", "part": "03_language.md"},
  "1-": {"stack": "( n1 -- n2 )", "kind": "word", "group": "arithmetic", "desc": "Subtracts 1 from n1. The same as 1 -, in one word. -32768 becomes 32767.", "example": "5 1- .                   \\ expect: 4\n-32768 1- .              \\ expect: 32767", "part": "03_language.md"},
  "2DROP": {"stack": "( x1 x2 -- )", "kind": "word", "group": "stack", "desc": "Removes the top two numbers from the stack.", "example": "1 2 3 4 2DROP . .        \\ expect: 2 1", "part": "03_language.md"},
  "2DUP": {"stack": "( x1 x2 -- x1 x2 x1 x2 )", "kind": "word", "group": "stack", "desc": "Copies the top two numbers, as a pair.", "example": "3 4 2DUP + . . .         \\ expect: 7 4 3", "part": "03_language.md"},
  ":": {"stack": "( \"name\" -- )", "kind": "defining word", "group": "dictionary", "desc": "Starts a definition: reads name and makes it a new word, then compiles the words that follow instead of running them, until ;. The name is known as soon as it is read, so a definition can call itself. Only the first 31 characters of a name count, and lower case is folded to upper.", "example": ": SQUARE DUP * ;\n5 SQUARE .               \\ expect: 25\n: SUM DUP 0= IF EXIT THEN\nDUP 1- SUM + ;\n5 SUM .                  \\ expect: 15\n: BAD 1 NOSUCH ;         \\ expect: NOSUCH ?", "part": "03_language.md"},
  ";": {"stack": "( -- )", "kind": "immediate word", "group": "dictionary", "desc": "Ends the definition that : began: compiles a return, makes the word complete and goes back to running what you type. It is immediate, so it runs even while a definition is being compiled.", "example": ": TWICE DUP + ;\n4 TWICE .                \\ expect: 8", "part": "03_language.md"},
  "<": {"stack": "( n1 n2 -- flag )", "kind": "word", "group": "arithmetic", "desc": "Leaves -1 (true) if n1 is less than n2, comparing them as signed numbers, and 0 (false) if it is not.", "example": "3 4 < . 4 3 < . 3 3 < .  \\ expect: -1 0 0", "part": "03_language.md"},
  "=": {"stack": "( x1 x2 -- flag )", "kind": "word", "group": "arithmetic", "desc": "Leaves -1 (true) if x1 and x2 are the same cell, and 0 (false) if they are not.", "example": "3 3 = . 3 4 = .          \\ expect: -1 0\n65535 -1 = .             \\ expect: -1", "part": "03_language.md"},
  ">": {"stack": "( n1 n2 -- flag )", "kind": "word", "group": "arithmetic", "desc": "Leaves -1 (true) if n1 is greater than n2, comparing them as signed numbers, and 0 (false) if it is not.", "example": "4 3 > . 3 4 > . 3 3 > .  \\ expect: -1 0 0", "part": "03_language.md"},
  "?DUP": {"stack": "( x -- 0 | x x )", "kind": "word", "group": "stack", "desc": "Copies the top number only if it is not 0; a 0 is left as it is, once. Before IF, it leaves the number for the test to use up and a copy for the code after it, but only when the number is not 0, so the false branch has nothing to drop.", "example": "5 ?DUP . .               \\ expect: 5 5\n0 ?DUP .                 \\ expect: 0\n: ?PRINT ?DUP IF . THEN ;\n7 ?PRINT                 \\ expect: 7\n0 ?PRINT", "part": "03_language.md"},
  "@": {"stack": "( addr -- x )", "kind": "word", "group": "memory", "desc": "Leaves the cell stored at addr: the byte at addr is the low half, the byte at addr+1 the high half. The cell is signed, so a stored 65535 is fetched as -1.", "example": "VARIABLE V\n99 V !\nV @ .                    \\ expect: 99\n65535 V !  V @ .         \\ expect: -1", "part": "03_language.md"},
  "ABORT": {"stack": "( -- )", "kind": "word", "group": "errors", "desc": "Gives up: empties both stacks, stops everything that is running, however deep, and returns to the prompt. Nothing after it on the line runs, and no OK is printed. Nothing is printed by ABORT itself; print your reason first.", "example": "1.5 42 ABORT 99 .\nFDEPTH .                 \\ expect: 0\nDROP                     \\ expect: STACK?", "part": "03_language.md"},
  "ABS": {"stack": "( n1 -- n2 )", "kind": "word", "group": "arithmetic", "desc": "Leaves the size of n1 without its sign. -32768 has no positive partner in a cell, so it stays -32768.", "example": "-5 ABS . 5 ABS .         \\ expect: 5 5\n-32768 ABS .             \\ expect: -32768", "part": "03_language.md"},
  "ACCEPT": {"stack": "( addr n -- len )", "kind": "word", "group": "I/O", "desc": "Reads a line from the keyboard into memory at addr and leaves the number of characters typed, len. Each character is stored as it is typed and shown at the print position. ENTER ends the line (it is not stored and not shown). DELETE (CAPS SHIFT and 0) takes back the last character. Once n characters are in, further keys are ignored until ENTER or DELETE.", "example": "CREATE BUF 20 ALLOT\nBUF 20 ACCEPT SPACE .    \\ expect: HELLO 5\nBUF 5 TYPE               \\ expect: HELLO\nBUF 3 ACCEPT SPACE .     \\ expect: ABC 3\nBUF 20 ACCEPT CR .       \\ expect: AB|2", "part": "04_machine.md"},
  "ALLOT": {"stack": "( n -- )", "kind": "word", "group": "memory", "desc": "Moves HERE by n bytes and writes nothing. A positive n reserves room, usually for the data field of a word just made with CREATE; a negative n gives room back. The reserved bytes are not cleared.", "example": "CREATE BUF 10 ALLOT\nHERE BUF - .             \\ expect: 10\n-4 ALLOT\nHERE BUF - .             \\ expect: 6", "part": "03_language.md"},
  "AND": {"stack": "( n1 n2 -- n3 )", "kind": "word", "group": "arithmetic", "desc": "Combines n1 and n2 bit by bit: a bit of the result is 1 only where both have a 1. Because a true flag is -1 (every bit set) and a false flag is 0, AND also joins two flags.", "example": "10 12 AND .              \\ expect: 8\n-1 255 AND .             \\ expect: 255\n3 4 < 4 5 < AND .        \\ expect: -1", "part": "03_language.md"},
  "ARRAY": {"stack": "( n \"name\" -- )", "kind": "defining word", "group": "memory", "desc": "Defines name as an array of n cells, all 0. Executing name leaves the address of its first cell; the address of element i, counting from 0, is i CELLS name +. Nothing checks the index.", "example": "5 ARRAY NUMS\n99 3 CELLS NUMS + !\n3 CELLS NUMS + @ .       \\ expect: 99\n0 CELLS NUMS + @ .       \\ expect: 0", "part": "03_language.md"},
  "AT-XY": {"stack": "( col row -- )", "kind": "word", "group": "I/O", "desc": "Moves the print position to column col (0 is the left, 31 the right) and row row (0 is the top, 22 the last row for output). The next EMIT, ., .\" or TYPE prints there.", "example": "CLS 10 0 AT-XY 65 EMIT   \\ expect:           A\n0 2 AT-XY 66 EMIT        \\ expect: |B", "part": "04_machine.md"},
  "BEEP": {"stack": "( n -- ) ( F: seconds -- )", "kind": "word", "group": "sound", "desc": "Plays a note on channel A of the AY sound chip and waits until it ends. n is the pitch in semitones from middle C: 0 is middle C, 12 the C above it, -12 the C below. The length is seconds, a decimal on the float stack, so write it with a decimal point: 0 0.5 BEEP plays middle C for half a second.", "example": "0 0.25 BEEP  4 0.25 BEEP         \\ C, E\n7 0.25 BEEP                              \\ G\n: AY@ 245 OUT 246 IN ;\n0 0.02 BEEP  0 AY@ . 1 AY@ .             \\ expect: 165 1\n12 0.02 BEEP  0 AY@ . 1 AY@ .            \\ expect: 211 0\n70 0.02 BEEP                             \\ nothing: out of range", "part": "04_machine.md"},
  "BEGIN": {"stack": "( -- )", "kind": "compile-only word", "group": "control", "desc": "Marks the start of a loop that UNTIL or REPEAT closes. It compiles nothing and does nothing when the loop runs.", "example": ": COUNTDOWN 3 BEGIN DUP .\n1- DUP 0= UNTIL DROP ;\nCOUNTDOWN                \\ expect: 3 2 1", "part": "03_language.md"},
  "BORDER": {"stack": "( n -- )", "kind": "word", "group": "graphics", "desc": "Sets the border colour to n, 0 to 7 (see the colours at the head of this part). Only the low three bits of n count: 9 gives blue, as 1 does. The border takes the colour at once and keeps it until the next BORDER.", "example": "2 BORDER                 \\ red border\n0 BORDER                 \\ black", "part": "04_machine.md"},
  "BREAK?": {"stack": "( -- flag )", "kind": "word", "group": "I/O", "desc": "Leaves true (-1) while CAPS SHIFT and SPACE are held down, false (0) otherwise. It reads the keyboard itself, so it does not use up the key that KEY? and KEY see. A program that checks BREAK? can finish what it is doing before it stops; otherwise BREAK stops it at once.", "example": "BREAK? .                 \\ expect: 0\n: WAIT BEGIN BREAK? UNTIL ;\nWAIT 5 .                 \\ expect: 5", "part": "04_machine.md"},
  "BRIGHT": {"stack": "( n -- )", "kind": "word", "group": "graphics", "desc": "Chooses bright (1) or normal (0) colours for what is drawn and printed from now on. Only bit 0 of n counts: 2 is 0 and 3 is 1. It does not change the other colour settings, nor what is already on the screen.", "example": "1 BRIGHT CLS 22528 C@ .  \\ expect: 120\n0 BRIGHT CLS 22528 C@ .  \\ expect: 56", "part": "04_machine.md"},
  "C!": {"stack": "( c addr -- )", "kind": "word", "group": "memory", "desc": "Stores the low byte of c at addr. The high byte of c is dropped.", "example": "VARIABLE V\n-1 V !\n0 V C!\nV @ .                    \\ expect: -256\n300 V C!  V C@ .         \\ expect: 44", "part": "03_language.md"},
  "C,": {"stack": "( c -- )", "kind": "word", "group": "memory", "desc": "Compiles the low byte of c at HERE and moves HERE on by 1.", "example": "CREATE B 3 C, 4 C, 5 C,\nB C@ .                   \\ expect: 3\nB 2 + C@ .               \\ expect: 5", "part": "03_language.md"},
  "C@": {"stack": "( addr -- c )", "kind": "word", "group": "memory", "desc": "Leaves the byte at addr, 0 to 255. It is never negative.", "example": "VARIABLE V\n200 V C!\nV C@ .                   \\ expect: 200", "part": "03_language.md"},
  "CATCH": {"stack": "( xt -- 0 | n )", "kind": "word", "group": "errors", "desc": "Runs the word whose execution token is xt. If it finishes, CATCH leaves what it left and then 0. If a THROW happens inside it, however deep, the stacks go back to the depth they had when CATCH began (less xt) and CATCH leaves the thrown number n. Nothing in between runs.", "example": ": SAFE 5 3 + ;\n: RISKY 42 THROW ;\n' SAFE CATCH . .         \\ expect: 0 8\n' RISKY CATCH .          \\ expect: 42\n1 2 ' RISKY CATCH . . .  \\ expect: 42 2 1", "part": "03_language.md"},
  "CELLS": {"stack": "( n1 -- n2 )", "kind": "word", "group": "memory", "desc": "Leaves n2, twice n1: the number of bytes in n1 cells. Use it to turn an element number into an offset: 3 CELLS ARR + is the address of element 3.", "example": "3 CELLS .                \\ expect: 6\n40000 CELLS .            \\ expect: 14464", "part": "03_language.md"},
  "CHAR": {"stack": "( \"name\" -- c )", "kind": "word", "group": "strings", "desc": "Reads the next word from the line and leaves the code of its first character, exactly as typed: CHAR a is 97 and CHAR A is 65.", "example": "CHAR A .                 \\ expect: 65\nCHAR a .                 \\ expect: 97\nCHAR hello .             \\ expect: 104", "part": "03_language.md"},
  "CHR": {"stack": "( c -- addr len )", "kind": "word", "group": "strings", "desc": "Makes a string of one character, the low byte of c, and leaves its address and length (always 1). The character is kept in a single buffer that every CHR uses, so the string lasts only until the next CHR.", "example": "65 CHR TYPE              \\ expect: A\n321 CHR TYPE             \\ expect: A", "part": "03_language.md"},
  "CIRCLE": {"stack": "( x y r -- )", "kind": "EXROM word", "group": "graphics", "desc": "Draws the outline of a circle of radius r pixels with its centre at pixel (x, y), in the current ink, paper, bright and flash. The part of the circle that is off the screen is not drawn: x, y and r are signed numbers, so the centre may be off the screen. A radius of 0 draws the centre point. A negative radius draws nothing.", "example": "CLS 0 18 AT-XY                           \\ draws\n100 100 30 CIRCLE                       \\ draws\n19600 C@ .                               \\ expect: 32", "part": "04_machine.md"},
  "CLS": {"stack": "( -- )", "kind": "word", "group": "I/O", "desc": "Clears the screen to the current paper colour and ink, and moves the print position to column 0 of row 0. The bitmap is cleared and every attribute cell is set to the colours chosen by INK, PAPER, BRIGHT and FLASH, so CLS keeps the colours you chose, as Sinclair BASIC's does. The border is not changed. In HIRES mode the second display file is cleared to the same colours.", "example": "2 INK 3 PAPER CLS 22528 C@ .   \\ expect: 26", "part": "04_machine.md"},
  "CODE": {"stack": "( addr len -- c )", "kind": "word", "group": "strings", "desc": "Leaves the code of the first character of the string. It is DROP C@: the length is not looked at, so for an empty string it is the byte at addr.", "example": "S\" A\" CODE .             \\ expect: 65\nS\" ABC\" CODE .           \\ expect: 65", "part": "03_language.md"},
  "CONSTANT": {"stack": "( x \"name\" -- )", "kind": "defining word", "group": "memory", "desc": "Defines name as a word that leaves x. The value is fixed when name is made; to keep a number that changes use VARIABLE.", "example": "100 CONSTANT LIMIT\nLIMIT .                  \\ expect: 100\nLIMIT 1+ .               \\ expect: 101", "part": "03_language.md"},
  "COS": {"stack": "( F: f1 -- f2 )", "kind": "word", "group": "float", "desc": "Leaves the cosine of the angle f1, given in radians. It is accurate to about 9 decimal places.", "example": "0.0 COS F.               \\ expect: 1.0000\n2.0 COS F.               \\ expect: -0.4161\n60.0 RAD COS F.          \\ expect: 0.5000", "part": "03_language.md"},
  "COUNT": {"stack": "( caddr -- addr len )", "kind": "word", "group": "strings", "desc": "Turns a counted string into an address and a length. A counted string is a length byte followed by the characters, as STRING makes and PLACE fills; caddr is the address of the length byte. addr is caddr+1 and len is the length byte.", "example": "10 STRING NAME\nS\" ADA\" NAME PLACE\nNAME COUNT TYPE          \\ expect: ADA\nNAME COUNT . DROP        \\ expect: 3", "part": "03_language.md"},
  "CR": {"stack": "( -- )", "kind": "word", "group": "I/O", "desc": "Moves the print position to column 0 of the next row. It is 13 EMIT. Below row 22 the output scrolls up one row, and the new bottom row is cleared to the current colours.", "example": "65 EMIT CR 66 EMIT       \\ expect: A|B", "part": "04_machine.md"},
  "CREATE": {"stack": "( \"name\" -- )", "kind": "defining word", "group": "dictionary", "desc": "Defines name as a word that leaves the address of its data field, the first byte after the word, which is where HERE stands just after CREATE. It reserves nothing: follow it with , C, or ALLOT to fill or reserve the data. With DOES> a defining word can give its words behaviour of their own.", "example": "CREATE PRIMES 2 , 3 , 5 , 7 ,\nPRIMES 2 CELLS + @ .     \\ expect: 5\nCREATE FLAGS 8 ALLOT\nHERE FLAGS - .           \\ expect: 8", "part": "03_language.md"},
  "DEG": {"stack": "( F: f1 -- f2 )", "kind": "word", "group": "float", "desc": "Turns an angle in radians into degrees: it multiplies by 180/pi.", "example": "PI DEG F.                \\ expect: 180.0000\nPI 2.0 F/ DEG F.         \\ expect: 90.0000", "part": "03_language.md"},
  "DO": {"stack": "( limit start -- )", "kind": "compile-only word", "group": "control", "desc": "Starts a counted loop that LOOP or +LOOP closes. When the loop runs, DO takes limit and start from the stack; the body runs with the index at start, then start+1, and so on, until the index reaches limit. I gives the index.", "example": ": FIVE 5 0 DO I . LOOP ;\nFIVE                     \\ expect: 0 1 2 3 4\n: ONCE 3 3 DO I . LEAVE LOOP ;\nONCE                     \\ expect: 3", "part": "03_language.md"},
  "DOES>": {"stack": "( -- )", "kind": "word", "group": "dictionary", "desc": "Used in a defining word, after CREATE. When the defining word runs, DOES> changes the word CREATE just made, so that when it runs it first leaves its data-field address and then runs the words that follow DOES>. DOES> also ends the defining word's own run there: the words after it belong to the new words only.", "example": ": CONST CREATE , DOES> @ ;\n5 CONST FIVE\nFIVE .                   \\ expect: 5\n: TABLE CREATE 10 , 20 , 30 ,\nDOES> SWAP CELLS + @ ;\nTABLE NUMS", "part": "03_language.md"},
  "DROP": {"stack": "( x -- )", "kind": "word", "group": "stack", "desc": "Removes the top number from the stack.", "example": "1 2 3 DROP . .           \\ expect: 2 1", "part": "03_language.md"},
  "DUP": {"stack": "( x -- x x )", "kind": "word", "group": "stack", "desc": "Copies the top number, so that the stack holds it twice.", "example": "7 DUP . .                \\ expect: 7 7\n5 DUP * .                \\ expect: 25", "part": "03_language.md"},
  "EDIT": {"stack": "( \"name\" -- )", "kind": "EXROM word", "group": "dictionary", "desc": "Opens the full-screen editor on the line store, the lines you have typed. EDIT name puts the cursor on the newest line in which : is followed directly by name; a bare EDIT opens a new empty line at the end. BREAK (CAPS SHIFT + SPACE) leaves the editor, clears the screen and runs the lines you changed or added, in order.", "example": ": SQ DUP + ;\nEDIT SQ\n5 SQ .                   \\ expect: 25", "part": "03_language.md"},
  "ELSE": {"stack": "( -- )", "kind": "compile-only word", "group": "control", "desc": "Used between IF and THEN. The words before it run if the flag given to IF was true; the words after it run if it was false. At run time, ELSE jumps over the words that follow it, to THEN.", "example": ": SIGN? 0 < IF 1 ELSE 2\nTHEN . ;\n-5 SIGN?                 \\ expect: 1\n5 SIGN?                  \\ expect: 2", "part": "03_language.md"},
  "EMIT": {"stack": "( c -- )", "kind": "word", "group": "I/O", "desc": "Prints the character with code c at the print position, in the current ink, paper, bright and flash, and moves the position one column to the right. After column 31 it moves to the start of the next row. Code 13 starts a new line instead of printing a glyph (see CR). Printing below row 22 scrolls the output up a row.", "example": "72 EMIT 73 EMIT          \\ expect: HI\nCLS 0 0 AT-XY 143 EMIT   \\ draws\n16384 C@ . 16640 C@ .    \\ expect: 255 255", "part": "04_machine.md"},
  "ENVELOPE": {"stack": "( period shape -- )", "kind": "word", "group": "sound", "desc": "Sets the AY chip's envelope generator: period (16 bits) goes to registers 11 and 12 and shape (the low four bits) to register 13. The envelope changes a channel's volume over time, and has effect only for a channel whose volume register has bit 4 set; VOLUME always clears that bit, so switch it on with SOUND: 8 16 SOUND for channel A.", "example": ": AY@ 245 OUT 246 IN ;\n1000 14 ENVELOPE\n11 AY@ . 12 AY@ . 13 AY@ .       \\ expect: 232 3 14\n8 16 SOUND  254 MIXER               \\ channel A follows it\n0 400 TONE\n8 0 SOUND                          \\ silent again", "part": "04_machine.md"},
  "EXECUTE": {"stack": "( xt -- )", "kind": "word", "group": "control", "desc": "Runs the word whose execution token xt is on the stack. ' and ['] give an xt. EXECUTE is the same as naming the word, except that the word is chosen while the program runs.", "example": ": SQ DUP * ;\n5 ' SQ EXECUTE .         \\ expect: 25\n3 4 ' + EXECUTE .        \\ expect: 7", "part": "03_language.md"},
  "EXIT": {"stack": "( -- )", "kind": "compile-only word", "group": "control", "desc": "Leaves the definition at once: the rest of the word after EXIT is not run, and control returns to the caller. It compiles a return in place. Inside a DO loop the loop is discarded properly, so EXIT is safe there.", "example": ": FIRST5 10 0 DO I 5 = IF\nI EXIT THEN LOOP -1 ;\nFIRST5 .                 \\ expect: 5\n: SUM DUP 0= IF EXIT THEN\nDUP 1- SUM + ;\n5 SUM .                  \\ expect: 15", "part": "03_language.md"},
  "F!": {"stack": "( addr -- ) ( F: f -- )", "kind": "word", "group": "float", "desc": "Takes a decimal off the float stack and stores it, in 5 bytes, at addr.", "example": "FVARIABLE X\n1.5 X F!\n2.25 X F!\nX F@ F.                  \\ expect: 2.2500", "part": "03_language.md"},
  "F*": {"stack": "( F: f1 f2 -- f3 )", "kind": "word", "group": "float", "desc": "Multiplies f1 by f2 and leaves the product.", "example": "2.0 3.0 F* F.            \\ expect: 6.0000\n1.5 FDUP F* F.           \\ expect: 2.2500\n1E38 10.0 F*             \\ expect: OUT OF RANGE", "part": "03_language.md"},
  "F+": {"stack": "( F: f1 f2 -- f3 )", "kind": "word", "group": "float", "desc": "Adds the top two decimals and leaves their sum. A decimal is a number with a fraction; it lives on its own stack, the float stack, so F+ does not touch the stack the whole numbers are on.", "example": "3.5 2.5 F+ F.            \\ expect: 6.0000\n0.1 0.2 F+ F.            \\ expect: 0.3000", "part": "03_language.md"},
  "F-": {"stack": "( F: f1 f2 -- f3 )", "kind": "word", "group": "float", "desc": "Subtracts f2 from f1 and leaves the difference.", "example": "6.0 2.5 F- F.            \\ expect: 3.5000\n2.5 6.0 F- F.            \\ expect: -3.5000", "part": "03_language.md"},
  "F.": {"stack": "( F: f -- )", "kind": "word", "group": "float", "desc": "Prints the decimal f with a fixed number of digits after the point, then a space. The number of digits is the one PLACES set, 4 when the machine is switched on. With 0 places the point is left out.", "example": "2.5 F.                   \\ expect: 2.5000\n-0.25 F.                 \\ expect: -0.2500\n1.0 3.0 F/ F.            \\ expect: 0.3333\n-0.00001 F.              \\ expect: 0.0000", "part": "03_language.md"},
  "F/": {"stack": "( F: f1 f2 -- f3 )", "kind": "word", "group": "float", "desc": "Divides f1 by f2 and leaves the quotient.", "example": "1.0 4.0 F/ F.            \\ expect: 0.2500\n1.0 3.0 F/ F.            \\ expect: 0.3333\n1.0 0.0 F/               \\ expect: DIVISION BY ZERO", "part": "03_language.md"},
  "F0<": {"stack": "( -- flag ) ( F: f -- )", "kind": "word", "group": "float", "desc": "Leaves -1 (true) on the data stack if the decimal is below zero, and 0 (false) if it is zero or above. The decimal is removed.", "example": "-3.0 F0< .               \\ expect: -1\n3.0 F0< . 0.0 F0< .      \\ expect: 0 0", "part": "03_language.md"},
  "F0=": {"stack": "( -- flag ) ( F: f -- )", "kind": "word", "group": "float", "desc": "Leaves -1 (true) on the data stack if the decimal is zero, and 0 (false) if it is not. The decimal is removed.", "example": "0.0 F0= .                \\ expect: -1\n1.0 F0= .                \\ expect: 0", "part": "03_language.md"},
  "F<": {"stack": "( -- flag ) ( F: f1 f2 -- )", "kind": "word", "group": "float", "desc": "Compares two decimals and leaves -1 (true) on the data stack if f1 is less than f2, and 0 (false) if it is not. The decimals are removed.", "example": "1.5 2.5 F< .             \\ expect: -1\n2.5 1.5 F< .             \\ expect: 0\n2.5 2.5 F< .             \\ expect: 0", "part": "03_language.md"},
  "F=": {"stack": "( -- flag ) ( F: f1 f2 -- )", "kind": "word", "group": "float", "desc": "Compares two decimals and leaves -1 (true) on the data stack if they are exactly equal, and 0 (false) if they are not. The decimals are removed.", "example": "2.5 2.5 F= .             \\ expect: -1\n2.5 1.5 F= .             \\ expect: 0", "part": "03_language.md"},
  "F>": {"stack": "( -- flag ) ( F: f1 f2 -- )", "kind": "word", "group": "float", "desc": "Compares two decimals and leaves -1 (true) on the data stack if f1 is greater than f2, and 0 (false) if it is not. The decimals are removed.", "example": "2.5 1.5 F> .             \\ expect: -1\n1.5 2.5 F> .             \\ expect: 0", "part": "03_language.md"},
  "F>S": {"stack": "( -- n ) ( F: f -- )", "kind": "word", "group": "float", "desc": "Turns the decimal f into a whole number by cutting off its fraction (toward zero, so -3.7 gives -3). The whole part must be from -32768 to 65535, the range a whole number can be typed in; above 32767 it is a negative cell, as it is when typed.", "example": "3.7 F>S .                \\ expect: 3\n-3.7 F>S .               \\ expect: -3\n40000.0 F>S .            \\ expect: -25536\n70000.0 F>S              \\ expect: OUT OF RANGE", "part": "03_language.md"},
  "F@": {"stack": "( addr -- ) ( F: -- f )", "kind": "word", "group": "float", "desc": "Fetches the decimal stored at addr and puts it on the float stack. A decimal takes 5 bytes of memory.", "example": "FVARIABLE X\n2.5 X F!\nX F@ X F@ F* F.          \\ expect: 6.2500", "part": "03_language.md"},
  "FABS": {"stack": "( F: f1 -- f2 )", "kind": "word", "group": "float", "desc": "Leaves the size of the decimal f1 without its sign.", "example": "-1.5 FABS F.             \\ expect: 1.5000\n1.5 FABS F.              \\ expect: 1.5000", "part": "03_language.md"},
  "FCONSTANT": {"stack": "( \"name\" -- ) ( F: f -- )", "kind": "defining word", "group": "float", "desc": "Makes a constant named name with the value of the decimal f, which is taken off the float stack. Typing name later puts that value on the float stack.", "example": "PI 2.0 F* FCONSTANT TAU\nTAU F.                   \\ expect: 6.2832\n2.5 FCONSTANT RATE\n: COST S>F RATE F* ;\n4 COST F.                \\ expect: 10.0000", "part": "03_language.md"},
  "FDEPTH": {"stack": "( -- n )", "kind": "word", "group": "float", "desc": "Leaves, on the data stack, the number of decimals now on the float stack.", "example": "FDEPTH .                 \\ expect: 0\n1.5 2.5 FDEPTH .         \\ expect: 2\nFDROP FDROP FDEPTH .     \\ expect: 0", "part": "03_language.md"},
  "FDROP": {"stack": "( F: f -- )", "kind": "word", "group": "float", "desc": "Removes the top decimal from the float stack.", "example": "1.5 2.5 FDROP F.         \\ expect: 1.5000", "part": "03_language.md"},
  "FDUP": {"stack": "( F: f -- f f )", "kind": "word", "group": "float", "desc": "Copies the top decimal.", "example": "1.5 FDUP F* F.           \\ expect: 2.2500", "part": "03_language.md"},
  "FILL": {"stack": "( x y -- )", "kind": "EXROM word", "group": "graphics", "desc": "Floods the region of the screen that contains pixel (x, y): every pixel joined to it, up, down, left or right, through pixels with the same value as it (all set, or all clear), is set, and the cells they fall in take the current ink, paper, bright and flash. Used inside a closed outline, it fills the shape. Used on the empty screen, it fills the whole screen.", "example": "CLS 0 18 AT-XY 50 50 20 CIRCLE           \\ draws\n2 INK 50 50 FILL                         \\ draws\n17094 C@ . 16384 C@ .                    \\ expect: 255 0\n22726 C@ .                               \\ expect: 58", "part": "04_machine.md"},
  "FLASH": {"stack": "( n -- )", "kind": "word", "group": "graphics", "desc": "Chooses flashing (1) or steady (0) colours for what is drawn and printed from now on. Only bit 0 of n counts. A flashing cell swaps its ink and paper in turn. It does not change the other colour settings, nor what is already on the screen.", "example": "1 FLASH CLS 22528 C@ .   \\ expect: 184\n0 FLASH CLS 22528 C@ .   \\ expect: 56", "part": "04_machine.md"},
  "FLOOR": {"stack": "( F: f1 -- f2 )", "kind": "word", "group": "float", "desc": "Rounds the decimal down, to the greatest whole value not above it. The result is still a decimal.", "example": "3.7 FLOOR F.             \\ expect: 3.0000\n-3.7 FLOOR F.            \\ expect: -4.0000\n-0.5 FLOOR F.            \\ expect: -1.0000", "part": "03_language.md"},
  "FMAX": {"stack": "( F: f1 f2 -- f3 )", "kind": "word", "group": "float", "desc": "Leaves the greater of the two decimals.", "example": "1.5 2.5 FMAX F.          \\ expect: 2.5000\n-1.5 -2.5 FMAX F.        \\ expect: -1.5000", "part": "03_language.md"},
  "FMIN": {"stack": "( F: f1 f2 -- f3 )", "kind": "word", "group": "float", "desc": "Leaves the lesser of the two decimals.", "example": "1.5 2.5 FMIN F.          \\ expect: 1.5000\n-1.5 -2.5 FMIN F.        \\ expect: -2.5000", "part": "03_language.md"},
  "FNEGATE": {"stack": "( F: f1 -- f2 )", "kind": "word", "group": "float", "desc": "Changes the sign of the decimal f1. Zero stays zero.", "example": "1.5 FNEGATE F.           \\ expect: -1.5000\n0.0 FNEGATE F.           \\ expect: 0.0000", "part": "03_language.md"},
  "FORGET": {"stack": "( \"name\" -- )", "kind": "word", "group": "dictionary", "desc": "Removes the word name and every word defined after it, and gives their memory back: HERE goes back to where name began. Words defined before it are untouched.", "example": ": A 1 ;  : B 2 ;  : C 3 ;\nFORGET B\nA .                      \\ expect: 1\nB                        \\ expect: B ?\nC                        \\ expect: C ?\nFORGET DUP               \\ expect: FORGET: BUILT-IN, REFUSED", "part": "03_language.md"},
  "FOVER": {"stack": "( F: f1 f2 -- f1 f2 f1 )", "kind": "word", "group": "float", "desc": "Copies the second decimal from the top onto the top.", "example": "1.5 2.5 FOVER F. F. F.   \\ expect: 1.5000 2.5000 1.5000", "part": "03_language.md"},
  "FREE": {"stack": "( -- n )", "kind": "word", "group": "memory", "desc": "Leaves the number of bytes between HERE and the top of the dictionary (address 53,248). It shrinks as you define words and use , C, and ALLOT.", "example": "FREE 100 ALLOT FREE - .  \\ expect: 100", "part": "03_language.md"},
  "FROUND": {"stack": "( F: f1 -- f2 )", "kind": "word", "group": "float", "desc": "Rounds the decimal to the nearest whole value. A value exactly half way goes away from zero. The result is still a decimal.", "example": "3.7 FROUND F.                \\ expect: 4.0000\n2.5 FROUND F. -2.5 FROUND F. \\ expect: 3.0000 -3.0000\n2.4 FROUND F.                \\ expect: 2.0000", "part": "03_language.md"},
  "FS.": {"stack": "( F: f -- )", "kind": "word", "group": "float", "desc": "Prints the decimal f in scientific notation: one digit, a point, the digits after it, E and the power of ten, then a space. The number of digits after the point is the one PLACES set.", "example": "12345.678 FS.            \\ expect: 1.2346E4\n-12345.678 FS.           \\ expect: -1.2346E4\n1E-6 FS.                 \\ expect: 1.0000E-6\n0.0 FS.                  \\ expect: 0.0000E0\n2 PLACES 12345.678 FS.   \\ expect: 1.23E4", "part": "03_language.md"},
  "FSQRT": {"stack": "( F: f1 -- f2 )", "kind": "word", "group": "float", "desc": "Leaves the square root of the decimal f1. The root of 0 is 0.", "example": "9.0 FSQRT F.             \\ expect: 3.0000\n2.0 FSQRT F.             \\ expect: 1.4142\n-1.0 FSQRT               \\ expect: INVALID ARGUMENT", "part": "03_language.md"},
  "FSWAP": {"stack": "( F: f1 f2 -- f2 f1 )", "kind": "word", "group": "float", "desc": "Exchanges the top two decimals.", "example": "1.5 2.5 FSWAP F. F.      \\ expect: 1.5000 2.5000", "part": "03_language.md"},
  "FVARIABLE": {"stack": "( \"name\" -- )", "kind": "defining word", "group": "float", "desc": "Makes a variable named name that holds a decimal, and sets it to 0. Typing name later puts its address on the stack, as VARIABLE does; use F@ and F! to read and write it.", "example": "FVARIABLE TOTAL\nTOTAL F@ F.              \\ expect: 0.0000\n1.5 TOTAL F!\nTOTAL F@ 2.25 F+ TOTAL F!\nTOTAL F@ F.              \\ expect: 3.7500", "part": "03_language.md"},
  "HERE": {"stack": "( -- addr )", "kind": "word", "group": "memory", "desc": "Leaves the address of the next free byte of the dictionary. Every new word, and every , C, and ALLOT, moves it up.", "example": "HERE 2 ALLOT HERE SWAP - .  \\ expect: 2\nCREATE PT 7 ,\nHERE PT - .                 \\ expect: 2", "part": "03_language.md"},
  "HIRES": {"stack": "( -- )", "kind": "word", "group": "graphics", "desc": "Switches the screen to high-resolution colour: the same 256 by 192 pixels, but each row of 8 pixels has its own ink and paper, instead of one pair for each 8 by 8 cell. The colours of a row of 8 pixels are kept in the second display file, which HIRES clears to white paper and black ink. The bitmap is not changed. NORMAL goes back.", "example": "HIRES\n1 INK 10 100 PLOT\n6 INK 10 101 PLOT\n27777 C@ 7 AND .             \\ expect: 1\n28033 C@ 7 AND .             \\ expect: 6\nNORMAL", "part": "04_machine.md"},
  "I": {"stack": "( -- n )", "kind": "word", "group": "control", "desc": "Leaves the index of the innermost DO loop.", "example": ": THREE 3 0 DO I . LOOP ;\nTHREE                    \\ expect: 0 1 2\n: FROM2 4 2 DO I . LOOP ;\nFROM2                    \\ expect: 2 3", "part": "03_language.md"},
  "IF": {"stack": "( flag -- )", "kind": "compile-only word", "group": "control", "desc": "Takes a flag. If it is not 0, the words up to ELSE or THEN run; if it is 0 they are skipped (and the words after ELSE run instead). Any number but 0 counts as true.", "example": ": TEST IF 1 ELSE 2 THEN . ;\n5 TEST                   \\ expect: 1\n0 TEST                   \\ expect: 2\n: AFTER IF 11 . THEN 12 . ;\n0 AFTER                  \\ expect: 12\n-1 AFTER                 \\ expect: 11 12", "part": "03_language.md"},
  "IMMEDIATE": {"stack": "( -- )", "kind": "word", "group": "dictionary", "desc": "Marks the newest word immediate: from now on it runs at once even inside a definition, instead of being compiled. Put it straight after the ; of the definition.", "example": ": HI .\" hi \" ; IMMEDIATE\n: T HI .\" there\" ;       \\ expect: hi\nT                        \\ expect: there", "part": "03_language.md"},
  "IN": {"stack": "( port -- c )", "kind": "word", "group": "I/O", "desc": "Reads one byte from the Z80 port numbered port and leaves it, 0 to 255. All 16 bits of port go to the processor, so the high byte can select a keyboard half-row as it does in Sinclair BASIC's IN.", "example": "8 245 OUT 12 246 OUT     \\ the sound chip: register 8 gets 12\n8 245 OUT 246 IN .       \\ expect: 12\n32766 IN 31 AND .        \\ expect: 31", "part": "04_machine.md"},
  "INK": {"stack": "( n -- )", "kind": "word", "group": "graphics", "desc": "Chooses the ink colour, 0 to 7, for what is drawn and printed from now on: EMIT, PLOT, LINE and the shapes use it. Only the low three bits of n count: 9 is the same as 1. It does not change the paper, bright or flash settings, nor anything already on the screen.", "example": "2 INK CLS 22528 C@ .     \\ expect: 58\n9 INK CLS 22528 C@ .     \\ expect: 57\n0 INK", "part": "04_machine.md"},
  "INPUT": {"stack": "( -- n )", "kind": "word", "group": "I/O", "desc": "Reads a line of at most eight characters from the keyboard as ACCEPT does, and leaves its value as a decimal integer, as VAL reads it. A line that is empty, or has anything but digits and a leading minus sign in it, gives 0. A value that does not fit in a cell wraps round: 40000 gives -25536.", "example": "INPUT 2 * .              \\ expect: 123246\nINPUT .                  \\ expect: ABC0\nINPUT .                  \\ expect: 40000-25536", "part": "04_machine.md"},
  "INVERT": {"stack": "( n1 -- n2 )", "kind": "word", "group": "arithmetic", "desc": "Flips every one of the 16 bits of n1. The result is -n1 - 1.", "example": "0 INVERT .               \\ expect: -1\n5 INVERT .               \\ expect: -6", "part": "03_language.md"},
  "J": {"stack": "( -- n )", "kind": "word", "group": "control", "desc": "Leaves the index of the loop around the innermost one: in a DO loop inside another, I is the inner index and J the outer.", "example": ": GRID 2 0 DO 2 0 DO\nJ . I . LOOP LOOP ;\nGRID                     \\ expect: 0 0 0 1 1 0 1 1", "part": "03_language.md"},
  "KEY": {"stack": "( -- c )", "kind": "word", "group": "I/O", "desc": "Waits for a key and leaves its code. The key is not shown. Letters give their lower-case ASCII codes unless CAPS SHIFT is held; ENTER gives 13, DELETE (CAPS SHIFT and 0) gives 8, and the cursor keys (CAPS SHIFT and 5, 6, 7, 8) give 1 (left), 2 (down), 3 (up) and 4 (right).", "example": ": ASK .\" KEY: \" KEY . ;\nASK                      \\ expect: KEY: 65\nKEY .                    \\ expect: 13", "part": "04_machine.md"},
  "KEY?": {"stack": "( -- flag )", "kind": "word", "group": "I/O", "desc": "Leaves true (-1) if a key has been pressed and not yet read, false (0) if not. It does not wait and does not use the key up, so KEY? IF KEY ... THEN reads it.", "example": "KEY? .                   \\ expect: 0\n: G KEY? IF KEY ELSE 0 THEN ;\nG .                      \\ expect: 0", "part": "04_machine.md"},
  "LEAVE": {"stack": "( -- )", "kind": "compile-only word", "group": "control", "desc": "Ends the innermost DO loop at once: the words between LEAVE and LOOP are skipped, and the program carries on after LOOP. A loop can hold any number of LEAVEs, usually inside an IF.", "example": ": UPTO3 10 0 DO I 3 =\nIF LEAVE THEN I . LOOP 99 . ;\nUPTO3                    \\ expect: 0 1 2 99", "part": "03_language.md"},
  "LEFT": {"stack": "( addr len n -- addr len2 )", "kind": "word", "group": "strings", "desc": "Leaves the first n characters of the string: the same address, and len2 the smaller of n and len. Nothing is copied. If n is len or more, or more than 255, or negative, the string is left whole.", "example": ": HAY S\" HELLO WORLD\" ;\nHAY 5 LEFT TYPE          \\ expect: HELLO\nHAY 99 LEFT TYPE         \\ expect: HELLO WORLD\nHAY 0 LEFT . DROP        \\ expect: 0", "part": "03_language.md"},
  "LEN": {"stack": "( caddr -- n )", "kind": "word", "group": "strings", "desc": "Leaves the length byte of a counted string, the kind STRING makes: n is how many characters it holds now.", "example": "10 STRING NAME\nNAME LEN .               \\ expect: 0\nS\" ADA\" NAME PLACE\nNAME LEN .               \\ expect: 3", "part": "03_language.md"},
  "LINE": {"stack": "( x1 y1 x2 y2 -- )", "kind": "word", "group": "graphics", "desc": "Draws a straight line from pixel (x1, y1) to pixel (x2, y2), both end points included, in the current ink, paper, bright and flash. The numbers are signed, and only the part of the line that is on the screen is drawn: the line from (0, 0) to (510, 382) is the diagonal of the screen.", "example": "CLS 0 5 AT-XY 0 0 31 0 LINE              \\ draws\n16384 C@ . 16387 C@ .            \\ expect: 255 255\n16388 C@ .                       \\ expect: 0\n-10 1 300 1 LINE                         \\ draws\n16640 C@ . 16671 C@ .                    \\ expect: 255 255", "part": "04_machine.md"},
  "LIST-DEFS": {"stack": "( -- )", "kind": "word", "group": "dictionary", "desc": "Lists the colon definitions in the line store, oldest first, each on its own row: its number from 0, then : and the first 20 characters of its source. It lists only the first 16.", "example": ": AA DUP + ;\n: BB DUP - ;\n: LONG-ONE 1 2 3 4 5 + + + + ;\nLIST-DEFS                \\ expect: 0: : AA DUP + ;|1: : BB DUP - ;|2: : LONG-ONE 1 2 3 4 5", "part": "03_language.md"},
  "LITERAL": {"stack": "( n -- )", "kind": "compile-only word", "group": "dictionary", "desc": "Used inside a definition, with [ and ]: compiles n as a number in the definition, so that when the definition runs it leaves n. It is how a value worked out while compiling goes into the definition.", "example": ": SEVEN [ 3 4 + ] LITERAL ;\nSEVEN .                  \\ expect: 7\n5 LITERAL                \\ expect: LITERAL ?", "part": "03_language.md"},
  "LLIST": {"stack": "( -- )", "kind": "word", "group": "printer", "desc": "Prints on the ZX Printer the names of the words you have defined, one name to a line, the newest first. The ROM's own words are not listed. With nothing defined it prints nothing.", "example": ": SQUARE DUP * ;\n: CUBE DUP SQUARE * ;\nLLIST", "part": "04_machine.md"},
  "LOAD-LIB": {"stack": "( \"name\" -- )", "kind": "word", "group": "storage", "desc": "Loads the dictionary image that SAVE-LIB wrote to tape under name, and replaces your whole dictionary with it. Without a name, it loads the first dictionary image on the tape. The tape is searched from where it is playing: other tapes and images, and images with other names, are skipped. Type it at the prompt, not in a definition: it overwrites the dictionary, including the definition that called it.", "example": ": DOUBLER DUP + ;\n' LOAD-LIB CATCH DEMO .  \\ expect: -28\n4 DOUBLER .              \\ expect: 8", "part": "04_machine.md"},
  "LOAD-TEXT": {"stack": "( \"name\" -- )", "kind": "word", "group": "storage", "desc": "Loads the source text that SAVE-TEXT wrote to tape under name into the line store, replacing what it held, and then interprets it as if you had typed it at the prompt: its definitions are compiled and its other lines run. Without a name, it loads the first text on the tape. When the text has run, the rest of the line you typed goes on.", "example": "' LOAD-TEXT CATCH DEMO . \\ expect: -28", "part": "04_machine.md"},
  "LOOP": {"stack": "( -- )", "kind": "compile-only word", "group": "control", "desc": "Closes a DO loop. At run time it adds 1 to the index; if the index has not reached the limit, the program goes back to the first word after DO, otherwise it carries on after LOOP.", "example": ": ROW 4 1 DO I . LOOP ;\nROW                      \\ expect: 1 2 3", "part": "03_language.md"},
  "LOWER": {"stack": "( addr len -- addr len )", "kind": "word", "group": "strings", "desc": "Changes the letters A to Z of the string to a to z, in place, and leaves the string. Other characters are unchanged.", "example": ": GREETING S\" Hello, World\" ;\nGREETING LOWER TYPE      \\ expect: hello, world", "part": "03_language.md"},
  "LPRINT": {"stack": "( addr len -- )", "kind": "word", "group": "printer", "desc": "Prints the len characters at addr on the ZX Printer, 32 to a line: a longer text goes on over as many lines as it needs, and the last line is padded with spaces. len = 0 prints one blank line. Characters with no glyph (control codes) print as blanks.", "example": "S\" HELLO, PRINTER\" LPRINT\nCREATE LINE 5 ALLOT\n72 LINE C!  73 LINE 1+ C!\nLINE 2 LPRINT", "part": "04_machine.md"},
  "MAX": {"stack": "( n1 n2 -- n3 )", "kind": "word", "group": "arithmetic", "desc": "Leaves the greater of n1 and n2, comparing them as signed numbers.", "example": "5 3 MAX .                \\ expect: 5\n-5 -1 MAX .              \\ expect: -1\n32767 -32768 MAX .       \\ expect: 32767", "part": "03_language.md"},
  "MIN": {"stack": "( n1 n2 -- n3 )", "kind": "word", "group": "arithmetic", "desc": "Leaves the lesser of n1 and n2, comparing them as signed numbers.", "example": "5 3 MIN .                \\ expect: 3\n-5 -1 MIN .              \\ expect: -5\n32767 -32768 MIN .       \\ expect: -32768", "part": "03_language.md"},
  "MIXER": {"stack": "( mask -- )", "kind": "word", "group": "sound", "desc": "Writes mask to the AY chip's mixer, register 7, which chooses what each channel plays. A 0 bit switches a source on: bits 0, 1 and 2 are the tones of channels A, B and C, bits 3, 4 and 5 their noise. Bits 6 and 7 are not sound: they set the direction of the chip's two I/O ports (1 = output). Any value can be written there: STICK sets bit 6 to 0 itself before each read. 253 MIXER plays channel B's tone only; 255…", "example": ": AY@ 245 OUT 246 IN ;\n253 MIXER  7 AY@ .       \\ expect: 253\n-1 MIXER   7 AY@ .       \\ expect: 255", "part": "04_machine.md"},
  "MOD": {"stack": "( n1 n2 -- n3 )", "kind": "word", "group": "arithmetic", "desc": "Leaves the remainder of n1 divided by n2. The remainder has the sign of n1. Dividing by zero is not an error: the remainder is 0.", "example": "17 5 MOD .               \\ expect: 2\n-17 5 MOD . 17 -5 MOD .  \\ expect: -2 2\n17 0 MOD .               \\ expect: 0", "part": "03_language.md"},
  "NEGATE": {"stack": "( n1 -- n2 )", "kind": "word", "group": "arithmetic", "desc": "Changes the sign of n1. -32768 has no positive partner in a cell, so it stays -32768.", "example": "5 NEGATE . -5 NEGATE .   \\ expect: -5 5\n-32768 NEGATE .          \\ expect: -32768", "part": "03_language.md"},
  "NOISE": {"stack": "( period -- )", "kind": "word", "group": "sound", "desc": "Sets the period of the AY chip's noise generator, 0 to 31 (the low five bits of period go to register 6). There is one noise generator, shared by all three channels; MIXER switches it onto a channel.", "example": ": AY@ 245 OUT 246 IN ;\n15 NOISE  6 AY@ .        \\ expect: 15\n33 NOISE  6 AY@ .        \\ expect: 1", "part": "04_machine.md"},
  "NORMAL": {"stack": "( -- )", "kind": "word", "group": "graphics", "desc": "Switches the screen back to the ordinary mode after HIRES: one ink and paper for each 8 by 8 cell. The bitmap is not changed.", "example": "HIRES NORMAL\n3 INK 100 100 PLOT\n22924 C@ 7 AND .        \\ expect: 3", "part": "04_machine.md"},
  "OR": {"stack": "( n1 n2 -- n3 )", "kind": "word", "group": "arithmetic", "desc": "Combines n1 and n2 bit by bit: a bit of the result is 1 where either has a 1. It also joins two flags.", "example": "15 240 OR .              \\ expect: 255\n0 -1 OR .                \\ expect: -1", "part": "03_language.md"},
  "OUT": {"stack": "( c port -- )", "kind": "word", "group": "I/O", "desc": "Writes the low byte of c to the Z80 port numbered port. All 16 bits of port go to the processor.", "example": "8 245 OUT 12 246 OUT     \\ sound chip register 8 (channel A volume) gets 12\n8 245 OUT 246 IN .       \\ expect: 12\n8 245 OUT 0 246 OUT     \\ and back to 0: silent", "part": "04_machine.md"},
  "OVER": {"stack": "( x1 x2 -- x1 x2 x1 )", "kind": "word", "group": "stack", "desc": "Copies the second number from the top onto the top.", "example": "1 2 OVER . . .           \\ expect: 1 2 1", "part": "03_language.md"},
  "PALETTE": {"stack": "( index value -- )", "kind": "word", "group": "graphics", "desc": "Sets entry index (0 to 63) of the ULAplus palette to value, a colour packed as GGGRRRBB: three bits of green, three of red, two of blue. It takes effect when ULAplus is on (see ULAPLUS), and changes every cell that uses that entry at once, with no need to redraw.", "example": "2 252 PALETTE            \\ entry 2: green 7, red 7, blue 0 (yellow)\n1 ULAPLUS\n0 ULAPLUS", "part": "04_machine.md"},
  "PAPER": {"stack": "( n -- )", "kind": "word", "group": "graphics", "desc": "Chooses the paper colour, 0 to 7, for what is drawn and printed from now on. Only the low three bits of n count: 9 is the same as 1. It does not change the ink, bright or flash settings, nor anything already on the screen.", "example": "5 PAPER 0 INK CLS 22528 C@ .             \\ expect: 40\n7 PAPER CLS 22528 C@ .                   \\ expect: 56", "part": "04_machine.md"},
  "PI": {"stack": "( F: -- f )", "kind": "word", "group": "float", "desc": "Puts the decimal nearest to pi, 3.14159265347, on the float stack. It is a little under the true pi, which is 3.14159265359.", "example": "PI F.                    \\ expect: 3.1416\nPI 2.0 F* F.             \\ expect: 6.2832", "part": "03_language.md"},
  "PICK": {"stack": "( xu ... x1 x0 u -- xu ... x1 x0 xu )", "kind": "word", "group": "stack", "desc": "Copies the u-th number down the stack to the top, counting the top number (just under u) as number 0: 0 PICK is DUP and 1 PICK is OVER.", "example": "10 20 30 2 PICK . . . .  \\ expect: 10 30 20 10\n7 8 1 PICK . . .         \\ expect: 7 8 7", "part": "03_language.md"},
  "PLACE": {"stack": "( addr len dest -- )", "kind": "word", "group": "strings", "desc": "Copies the len characters at addr into the counted string dest and sets its length byte to len. dest is usually a STRING buffer.", "example": "10 STRING NAME\nS\" HELLO\" NAME PLACE\nNAME COUNT TYPE          \\ expect: HELLO\nS\" HI\" NAME PLACE\nNAME COUNT TYPE          \\ expect: HI", "part": "03_language.md"},
  "PLACES": {"stack": "( n -- )", "kind": "word", "group": "float", "desc": "Sets the number of digits after the point that F. and FS. print: 0 to 9. The machine starts with 4. The setting stays until the next PLACES.", "example": "PI F.                    \\ expect: 3.1416\n2 PLACES PI F.           \\ expect: 3.14\n0 PLACES PI F.           \\ expect: 3\n9 PLACES PI F.           \\ expect: 3.141592653\n10 PLACES                \\ expect: OUT OF RANGE", "part": "03_language.md"},
  "PLOT": {"stack": "( x y -- )", "kind": "word", "group": "graphics", "desc": "Sets the pixel at column x (0 to 255, from the left) and row y (0 to 191, from the top), and gives the cell that holds it the current ink, paper, bright and flash. A pixel is only set, never cleared: plotting a set pixel changes nothing but the cell's colours. A point off the screen is not drawn, and is not an error.", "example": "CLS 0 5 AT-XY 0 0 PLOT                   \\ draws\n16384 C@ .                               \\ expect: 128\n255 191 PLOT  22527 C@ .                 \\ expect: 1\n300 0 PLOT  16389 C@ .                   \\ expect: 0", "part": "04_machine.md"},
  "POLYGON": {"stack": "( x1 y1 x2 y2 ... xn yn n -- )", "kind": "EXROM word", "group": "graphics", "desc": "Draws the outline of a closed shape with n corners, 3 to 12, at the pixels (x1, y1) to (xn, yn): a line from each corner to the next and from the last back to the first, in the current ink, paper, bright and flash. The first pair is deepest on the stack, the count n on top. An n below 3 or above 12 draws nothing and takes only n from the stack.", "example": "CLS 0 18 AT-XY                           \\ draws\n: TRI 100 40 140 40 100 80 3 ;\nTRI POLYGON                              \\ draws\n16559 C@ .                               \\ expect: 255\n10 10 20 20 2 POLYGON  . . . .           \\ expect: 20 20 10 10", "part": "04_machine.md"},
  "POLYGON-FILL": {"stack": "( x1 y1 x2 y2 ... xn yn n -- )", "kind": "EXROM word", "group": "graphics", "desc": "Fills the inside of the shape whose corners are (x1, y1) to (xn, yn), 3 to 12 corners, in the current ink, paper, bright and flash. Its arguments are those of POLYGON, but no outline is drawn. A point is inside if a line from it crosses the edges an odd number of times (the even-odd rule), so a shape whose edges cross itself has holes.", "example": "CLS 0 18 AT-XY                           \\ draws\n: TRI 100 40 140 40 100 80 3 ;\nTRI POLYGON-FILL                         \\ draws\n17101 C@ . 17105 C@ .                    \\ expect: 255 0", "part": "04_machine.md"},
  "QUIT": {"stack": "( -- )", "kind": "word", "group": "errors", "desc": "Gives up like ABORT but keeps the stacks as they are: stops everything that is running, however deep, and returns to the prompt. Nothing after it on the line runs, and no OK is printed.", "example": "5 QUIT 6 .\n.                        \\ expect: 5", "part": "03_language.md"},
  "RAD": {"stack": "( F: f1 -- f2 )", "kind": "word", "group": "float", "desc": "Turns an angle in degrees into radians: it multiplies by pi/180.", "example": "90.0 RAD F.              \\ expect: 1.5708\n45.0 RAD SIN F.          \\ expect: 0.7071", "part": "03_language.md"},
  "RANDOMIZE": {"stack": "( n -- )", "kind": "word", "group": "arithmetic", "desc": "Sets where the random numbers of RND start. The same n (not 0) always gives the same run of numbers. 0 means no fixed start: the next RND takes one from the frame counter (the time since switch-on, in frames) mixed with the processor's refresh counter, which differs from run to run.", "example": "7 RANDOMIZE 6 RND .      \\ expect: 3\n7 RANDOMIZE 6 RND .      \\ expect: 3\n6 RND .                  \\ expect: 5", "part": "03_language.md"},
  "RECT": {"stack": "( x0 y0 x1 y1 -- )", "kind": "EXROM word", "group": "graphics", "desc": "Fills the rectangle whose opposite corners are pixels (x0, y0) and (x1, y1), both corners included and given in either order, with ink, and gives the cells it covers the current ink, paper, bright and flash. Pixels are set, never cleared. The corners may be off the screen: the part of the rectangle on it is drawn, and one wholly off it draws nothing.", "example": "CLS 0 10 AT-XY 8 0 15 1 RECT             \\ draws\n16385 C@ . 16641 C@ .            \\ expect: 255 255\n16897 C@ .                       \\ expect: 0\n-8 0 3 0 RECT                            \\ draws\n16384 C@ .                               \\ expect: 240\n300 0 310 7 RECT                         \\ draws", "part": "04_machine.md"},
  "REPEAT": {"stack": "( -- )", "kind": "compile-only word", "group": "control", "desc": "Closes a BEGIN ... WHILE ... REPEAT loop: at run time it jumps back to BEGIN. The loop ends when WHILE finds a 0 flag.", "example": ": SMALLER 0 BEGIN DUP 3 <\nWHILE DUP . 1+ REPEAT DROP ;\nSMALLER                  \\ expect: 0 1 2", "part": "03_language.md"},
  "RIGHT": {"stack": "( addr len n -- addr2 len2 )", "kind": "word", "group": "strings", "desc": "Leaves the last n characters of the string: len2 the smaller of n and len, and addr2 the address of the first of them. Nothing is copied. If n is len or more, or more than 255, or negative, the string is left whole.", "example": ": HAY S\" HELLO WORLD\" ;\nHAY 5 RIGHT TYPE         \\ expect: WORLD\nHAY 99 RIGHT TYPE        \\ expect: HELLO WORLD\nHAY 0 RIGHT . DROP       \\ expect: 0", "part": "03_language.md"},
  "RND": {"stack": "( n1 -- n2 )", "kind": "word", "group": "arithmetic", "desc": "Leaves a random whole number from 0 up to n1 - 1: 6 RND is 0 to 5, each about equally likely. If n1 is 0 or negative the result is 0.", "example": "42 RANDOMIZE 10 RND .    \\ expect: 2\n10 RND .                 \\ expect: 8\n0 RND . -5 RND .         \\ expect: 0 0", "part": "03_language.md"},
  "ROT": {"stack": "( x1 x2 x3 -- x2 x3 x1 )", "kind": "word", "group": "stack", "desc": "Moves the third number from the top to the top.", "example": "1 2 3 ROT . . .          \\ expect: 1 3 2", "part": "03_language.md"},
  "S\"": {"stack": "( -- addr len )", "kind": "immediate word", "group": "strings", "desc": "Reads text up to the next \" and makes it a string. Inside a definition it compiles the text into the definition, and when the definition runs it leaves the address and length of that text. At the prompt it leaves the address and length at once. Write one space after S\"; the text starts at the next character and is kept as typed, upper and lower case alike.", "example": ": HI S\" Hello\" TYPE ;\nHI                       \\ expect: Hello\nS\" abc\" . DROP           \\ expect: 3", "part": "03_language.md"},
  "S>F": {"stack": "( n -- ) ( F: -- f )", "kind": "word", "group": "float", "desc": "Turns the whole number n into the same value as a decimal. It is exact. The decimal is put on the float stack.", "example": "42 S>F F.                \\ expect: 42.0000\n-7 S>F F.                \\ expect: -7.0000\n7 S>F 2 S>F F/ F.        \\ expect: 3.5000", "part": "03_language.md"},
  "SAVE-LIB": {"stack": "( \"name\" -- )", "kind": "word", "group": "storage", "desc": "Writes your whole dictionary, everything you have defined since switch-on or the last LOAD-LIB, to tape as a dictionary image under name (up to 10 characters; longer names are cut). The ROM's own words are not written. Later LOAD-LIB brings the words back, ready to run, much faster than SAVE-TEXT's source can be compiled.", "example": ": DOUBLER DUP + ;\nSAVE-LIB DEMO\n' SAVE-LIB CATCH DEMO .  \\ expect: 0\n' SAVE-LIB CATCH DEMO .  \\ expect: -28", "part": "04_machine.md"},
  "SAVE-TEXT": {"stack": "( \"name\" -- )", "kind": "word", "group": "storage", "desc": "Writes the line store, the source lines you have typed and committed (see EDIT), to tape under name (up to 10 characters; longer names are cut), one carriage-return-ended line after another. The line holding the SAVE-TEXT command is not part of it. LOAD-TEXT brings the text back and runs it; it loads into any version of the ROM.", "example": ": SQUARE DUP * ;\nSAVE-TEXT DEMO\n' SAVE-TEXT CATCH DEMO . \\ expect: 0\n' SAVE-TEXT CATCH DEMO . \\ expect: -28", "part": "04_machine.md"},
  "SEARCH": {"stack": "( addr1 len1 addr2 len2 -- addr3 len3 flag )", "kind": "word", "group": "strings", "desc": "Looks for the second string in the first. If it is found, addr3 len3 is the rest of the first string from the match on, and flag is true (-1). If not, addr3 len3 is the first string unchanged and flag is false (0). An empty second string is never found.", "example": ": HAY S\" HELLO WORLD\" ;\n: W S\" WORLD\" ;\n: LO S\" LO\" ;\n: NO S\" XYZ\" ;\nHAY W SEARCH . TYPE      \\ expect: -1 WORLD\nHAY LO SEARCH . TYPE     \\ expect: -1 LO WORLD", "part": "03_language.md"},
  "SGN": {"stack": "( n1 -- n2 )", "kind": "word", "group": "arithmetic", "desc": "Leaves -1 if n1 is below zero, 0 if it is zero, and 1 if it is above zero.", "example": "-8 SGN . 0 SGN . 40 SGN . \\ expect: -1 0 1", "part": "03_language.md"},
  "SIN": {"stack": "( F: f1 -- f2 )", "kind": "word", "group": "float", "desc": "Leaves the sine of the angle f1, given in radians (pi radians is 180 degrees; for degrees use RAD first). It is accurate to about 9 decimal places.", "example": "0.0 SIN F.               \\ expect: 0.0000\n1.0 SIN F.               \\ expect: 0.8415\n30.0 RAD SIN F.          \\ expect: 0.5000\nPI SIN FS.               \\ expect: 1.2154E-10", "part": "03_language.md"},
  "SOUND": {"stack": "( register value -- )", "kind": "word", "group": "sound", "desc": "Writes value (its low byte) to register register of the AY-3-8912 sound chip, numbered as the chip numbers them, 0 to 15. The chip keeps what it is given until you change it, so a tone goes on after the word that started it has ended. A register of 17 or more is ignored: nothing is written.", "example": ": AY@ 245 OUT 246 IN ;\n1 7 SOUND  1 AY@ .       \\ expect: 7\n2 300 SOUND  2 AY@ .     \\ expect: 44\n17 5 SOUND  256 33 SOUND \\ ignored\n2 251 SOUND  3 0 SOUND           \\ channel B, 439 Hz\n7 253 SOUND  9 15 SOUND", "part": "04_machine.md"},
  "SPACE": {"stack": "( -- )", "kind": "word", "group": "I/O", "desc": "Prints one space at the print position. It is 32 EMIT.", "example": "65 EMIT SPACE 66 EMIT    \\ expect: A B", "part": "04_machine.md"},
  "SPACES": {"stack": "( n -- )", "kind": "word", "group": "I/O", "desc": "Prints n spaces. With n = 0 it prints nothing.", "example": "65 EMIT 3 SPACES 66 EMIT \\ expect: A   B\n0 SPACES                 \\ prints nothing", "part": "04_machine.md"},
  "SPRITE-DEFINE": {"stack": "( slot row col -- )", "kind": "EXROM word", "group": "graphics", "desc": "Captures the picture on the screen at text row row, column col as the image of sprite slot (0 to 3). A sprite is 2 by 2 character cells, 16 by 16 pixels: the cells at (row, col), (row, col + 1), (row + 1, col) and (row + 1, col + 1), with their colours. Draw the picture on the screen with EMIT, PLOT, RECT or anything else, define it, and show it anywhere with SPRITE-SHOW.", "example": ": BOX 143 EMIT 143 EMIT ;\nCLS 5 5 AT-XY BOX                        \\ draws\n5 6 AT-XY BOX                             \\ draws\n0 5 5 SPRITE-DEFINE\nCLS 0 18 AT-XY                           \\ draws\n0 10 10 SPRITE-SHOW                      \\ draws", "part": "04_machine.md"},
  "SPRITE-HIDE": {"stack": "( slot -- )", "kind": "EXROM word", "group": "graphics", "desc": "Puts back the picture that SPRITE-SHOW covered with the sprite in slot, at the place it was shown. After this the sprite is no longer shown. It does nothing if the slot is not shown, or is more than 3.", "example": "CLS 5 5 AT-XY 143 EMIT                                           \\ draws\n0 5 5 SPRITE-DEFINE\nCLS 0 18 AT-XY                           \\ draws\n0 10 10 SPRITE-SHOW                      \\ draws\n18506 C@ .                              \\ expect: 255\n0 SPRITE-HIDE                            \\ draws", "part": "04_machine.md"},
  "SPRITE-SHOW": {"stack": "( slot row col -- )", "kind": "EXROM word", "group": "graphics", "desc": "Shows the sprite in slot (0 to 3) with its top left cell at text row row, column col: the screen under it is saved, and the sprite's picture and colours are drawn over it. It does nothing if the slot has no image (see SPRITE-DEFINE), if it is already shown, or if slot is above 3.", "example": ": BOX 143 EMIT 143 EMIT ;\nCLS 5 5 AT-XY BOX                        \\ draws\n5 6 AT-XY BOX                             \\ draws\n0 5 5 SPRITE-DEFINE\nCLS 0 18 AT-XY                           \\ draws\n0 10 10 SPRITE-SHOW                      \\ draws", "part": "04_machine.md"},
  "SQRT": {"stack": "( n1 -- n2 )", "kind": "word", "group": "arithmetic", "desc": "Leaves the square root of n1, with the fraction cut off: the greatest whole number whose square is not above n1. A negative n1 gives 0, with no error.", "example": "16 SQRT . 15 SQRT .      \\ expect: 4 3\n32767 SQRT .             \\ expect: 181\n-4 SQRT .                \\ expect: 0", "part": "03_language.md"},
  "STICK": {"stack": "( device -- value )", "kind": "word", "group": "I/O", "desc": "Reads joystick device, 1 or 2. The result is a number from 0 to 31: bits 0 to 3 are the four direction switches (a bit is 1 while that direction is pushed), and 16 is added while the fire button is pressed. 0 means nothing is pressed. With no joystick connected both give 0.", "example": "1 STICK .                \\ expect: 0\n2 STICK .                \\ expect: 0\n: AY@ 245 OUT 246 IN ;\n248 MIXER  1 STICK DROP  7 AY@ .   \\ expect: 184", "part": "04_machine.md"},
  "STR": {"stack": "( n -- addr len )", "kind": "word", "group": "strings", "desc": "Makes the decimal text of n, as . would print it but without the trailing space, and leaves its address and length. A negative number starts with -; the longest is -32768, six characters. The text is kept in one buffer that every STR uses, so it lasts only until the next STR.", "example": "-42 STR TYPE             \\ expect: -42\n1234 STR . DROP          \\ expect: 4\n0 STR TYPE               \\ expect: 0", "part": "03_language.md"},
  "STRING": {"stack": "( n \"name\" -- )", "kind": "defining word", "group": "strings", "desc": "Defines name as a counted-string buffer that can hold up to n characters, empty to start with. Executing name leaves its address. The buffer is a length byte followed by n bytes, so it takes n+1 bytes. Fill it with PLACE; read it with COUNT or LEN.", "example": "10 STRING NAME\nNAME LEN .               \\ expect: 0\nS\" ADA\" NAME PLACE\nNAME COUNT TYPE          \\ expect: ADA", "part": "03_language.md"},
  "SWAP": {"stack": "( x1 x2 -- x2 x1 )", "kind": "word", "group": "stack", "desc": "Exchanges the top two numbers.", "example": "1 2 SWAP . .             \\ expect: 1 2\n10 3 SWAP - .            \\ expect: -7", "part": "03_language.md"},
  "TAN": {"stack": "( F: f1 -- f2 )", "kind": "word", "group": "float", "desc": "Leaves the tangent of the angle f1, given in radians: the sine divided by the cosine.", "example": "1.0 TAN F.               \\ expect: 1.5574\nPI 4.0 F/ TAN F.         \\ expect: 1.0000\nPI 2.0 F/ TAN            \\ expect: DIVISION BY ZERO", "part": "03_language.md"},
  "THEN": {"stack": "( -- )", "kind": "compile-only word", "group": "control", "desc": "Ends an IF (or IF ... ELSE): the program carries on here, whichever way the flag went. It compiles nothing; it only settles where IF and ELSE jump to.", "example": ": AFTER IF 11 . THEN 12 . ;\n0 AFTER                  \\ expect: 12\n7 AFTER                  \\ expect: 11 12", "part": "03_language.md"},
  "THROW": {"stack": "( n -- )", "kind": "word", "group": "errors", "desc": "If n is 0, does nothing. Otherwise stops everything that is running and goes back to the nearest CATCH, which leaves n. With no CATCH, both stacks are emptied, a message for n is printed in place of OK, and the prompt returns.", "example": ": FAIL 42 THROW 1 . ;\n' FAIL CATCH .           \\ expect: 42\n0 THROW  5 .             \\ expect: 5\n-28 THROW                \\ expect: BREAK\n7 THROW                  \\ expect: ERROR 7", "part": "03_language.md"},
  "TONE": {"stack": "( channel period -- )", "kind": "word", "group": "sound", "desc": "Sets the pitch of channel channel (0 is A, 1 is B, 2 is C) of the AY chip to period, 0 to 4095. The note is 110,250 / period Hz: 0 251 TONE is about 439 Hz. A larger period is a lower note. The channel makes no sound until its volume is above 0 (VOLUME) and the mixer has its tone on (MIXER).", "example": ": AY@ 245 OUT 246 IN ;\n0 4095 TONE  0 AY@ . 1 AY@ .             \\ expect: 255 15\n254 MIXER  0 251 TONE             \\ pitch 439 Hz\n0 15 VOLUME                              \\ A plays\n0 0 VOLUME                               \\ silent", "part": "04_machine.md"},
  "TYPE": {"stack": "( addr len -- )", "kind": "word", "group": "I/O", "desc": "Prints the len characters that start at addr, as if each was given to EMIT. len is taken as a byte: 0 and 256 print nothing.", "example": "S\" HELLO\" TYPE           \\ expect: HELLO\nS\" HELLO\" DROP 3 TYPE    \\ expect: HEL", "part": "04_machine.md"},
  "UDG": {"stack": "( n -- addr )", "kind": "word", "group": "graphics", "desc": "Leaves the address of the 8 bytes that draw user-defined graphic n (0 to 20). Store the pattern there, one byte for each pixel row from the top, and EMIT the code 144 + n to draw it.", "example": "255 0 UDG C!  129 0 UDG 1 + C!\n255 0 UDG 2 + C!\nCLS 0 0 AT-XY 144 EMIT                   \\ draws\n16384 C@ . 16640 C@ .            \\ expect: 255 129\n16896 C@ .                       \\ expect: 255\n1 UDG 0 UDG - .                          \\ expect: 8", "part": "04_machine.md"},
  "ULAPLUS": {"stack": "( flag -- )", "kind": "word", "group": "graphics", "desc": "Turns the ULAplus palette on (when bit 0 of flag is 1) or off (when it is 0). With it on, the ink, paper, bright and flash of every cell choose one of 64 colours that PALETTE has set, instead of the eight of the ordinary hardware. The colour words and drawing words work as before.", "example": "2 252 PALETTE\n1 ULAPLUS                \\ on\n0 ULAPLUS                \\ off: the ordinary eight colours", "part": "04_machine.md"},
  "UNTIL": {"stack": "( flag -- )", "kind": "compile-only word", "group": "control", "desc": "Closes a BEGIN ... UNTIL loop. At run time it takes a flag: if it is 0 the program goes back to BEGIN, otherwise it carries on after UNTIL. The body runs at least once.", "example": ": TO3 0 BEGIN 1+ DUP .\nDUP 3 = UNTIL DROP ;\nTO3                      \\ expect: 1 2 3", "part": "03_language.md"},
  "UPPER": {"stack": "( addr len -- addr len )", "kind": "word", "group": "strings", "desc": "Changes the letters a to z of the string to A to Z, in place, and leaves the string. Other characters are unchanged.", "example": ": GREETING S\" Hello, World\" ;\nGREETING UPPER TYPE      \\ expect: HELLO, WORLD\nGREETING TYPE            \\ expect: HELLO, WORLD", "part": "03_language.md"},
  "VAL": {"stack": "( addr len -- n )", "kind": "word", "group": "strings", "desc": "Converts the decimal text of the string to a number. The text is digits with an optional - first. A string that is empty, is a lone -, or has any other character (a space, a +, a letter, a decimal point) gives 0, with no error.", "example": "S\" 1234\" VAL .           \\ expect: 1234\nS\" -17\" VAL .            \\ expect: -17\nS\" 12abc\" VAL .          \\ expect: 0", "part": "03_language.md"},
  "VARIABLE": {"stack": "( \"name\" -- )", "kind": "defining word", "group": "memory", "desc": "Defines name as a variable: a cell of memory, set to 0. Executing name leaves the cell's address; @ reads it and ! changes it.", "example": "VARIABLE COUNT-ME\nCOUNT-ME @ .             \\ expect: 0\n5 COUNT-ME !\nCOUNT-ME @ 1+ COUNT-ME !\nCOUNT-ME @ .             \\ expect: 6", "part": "03_language.md"},
  "VERIFY-LIB": {"stack": "( \"name\" -- )", "kind": "word", "group": "storage", "desc": "Compares the dictionary image on tape named name with your dictionary and changes nothing: it finishes quietly if they are the same, and gives TAPE ERROR if not. Without a name it checks the first dictionary image on the tape. Run it straight after SAVE-LIB, before defining anything else, to know the tape is good: a dictionary that has grown since no longer matches.", "example": ": DOUBLER DUP + ;\n' VERIFY-LIB CATCH DEMO .  \\ expect: -28", "part": "04_machine.md"},
  "VERIFY-TEXT": {"stack": "( \"name\" -- )", "kind": "word", "group": "storage", "desc": "Compares the text on tape named name with the line store and changes nothing: it finishes quietly if they are the same, and gives TAPE ERROR if not. The command line itself is not counted in the store. Without a name it checks the first text on the tape. A tape of a different length is a mismatch.", "example": "' VERIFY-TEXT CATCH DEMO . \\ expect: -28", "part": "04_machine.md"},
  "VLIST": {"stack": "( -- )", "kind": "word", "group": "dictionary", "desc": "Prints the name of every word in the dictionary, newest first, each followed by a space, ending with the oldest word of the ROM. The names wrap at the screen's edge and scroll; there are several screens of them.", "example": ": Q 1 ;\nVLIST                    \\ expect-end: DUP DROP", "part": "03_language.md"},
  "VOLUME": {"stack": "( channel level -- )", "kind": "word", "group": "sound", "desc": "Sets the volume of channel channel (0 is A, 1 is B, 2 is C) of the AY chip to level, 0 (silent) to 15 (loudest). Only the low four bits of level count. The volume is fixed: the channel does not follow the envelope.", "example": ": AY@ 245 OUT 246 IN ;\n2 15 VOLUME  10 AY@ .    \\ expect: 15\n2 20 VOLUME  10 AY@ .    \\ expect: 4\n2 0 VOLUME", "part": "04_machine.md"},
  "WHILE": {"stack": "( flag -- )", "kind": "compile-only word", "group": "control", "desc": "Used in BEGIN ... WHILE ... REPEAT. At run time it takes a flag: if it is not 0 the words up to REPEAT run; if it is 0 the loop ends and the program carries on after REPEAT. The test comes first, so the body may run no times.", "example": ": UPTO 0 BEGIN DUP 3 <\nWHILE DUP . 1+ REPEAT DROP ;\nUPTO                     \\ expect: 0 1 2\n: NONE 5 BEGIN DUP 3 <\nWHILE 1+ REPEAT . ;\nNONE                     \\ expect: 5", "part": "03_language.md"},
  "XOR": {"stack": "( n1 n2 -- n3 )", "kind": "word", "group": "arithmetic", "desc": "Combines n1 and n2 bit by bit: a bit of the result is 1 where exactly one of them has a 1. XOR with the same number twice gives the first number back.", "example": "10 12 XOR .              \\ expect: 6\n10 12 XOR 12 XOR .       \\ expect: 10", "part": "03_language.md"},
  "[": {"stack": "( -- )", "kind": "immediate word", "group": "dictionary", "desc": "Used inside a definition: switches from compiling to running. The words after [ run at once, up to ], and their results can go into the definition with LITERAL.", "example": ": SIX [ 2 3 * ] LITERAL ;\nSIX .                    \\ expect: 6", "part": "03_language.md"},
  "[']": {"stack": "( \"name\" -- )", "kind": "compile-only word", "group": "dictionary", "desc": "Used inside a definition: reads the next word from the line and compiles its execution token as a number. When the definition runs it leaves that xt (the run-time effect is ( -- xt )). It is ' done once, while compiling, instead of every time the word runs.", "example": ": SQ DUP * ;\n: RUN ['] SQ EXECUTE ;\n5 RUN .                  \\ expect: 25", "part": "03_language.md"},
  "[CHAR]": {"stack": "( \"name\" -- )", "kind": "compile-only word", "group": "strings", "desc": "Used inside a definition: reads the next word from the line, as CHAR does, and compiles the code of its first character as a literal. When the definition runs it leaves that code. At run time the stack effect is ( -- c ).", "example": ": STAR [CHAR] * ;\nSTAR .                   \\ expect: 42\n: LETTER [CHAR] hello ;\nLETTER .                 \\ expect: 104", "part": "03_language.md"},
  "\\": {"stack": "( -- )", "kind": "immediate word", "group": "dictionary", "desc": "Starts a comment that runs to the end of the line. It works at the prompt and inside a definition. Put a space after \\.", "example": "1 2 + .  \\ not read: 3 4 + .  \\ expect: 3\n: SHOW 5 \\ five\n. ;\nSHOW                          \\ expect: 5", "part": "03_language.md"},
  "]": {"stack": "( -- )", "kind": "word", "group": "dictionary", "desc": "Switches to compiling: the words after it are compiled, not run, until ; or [. Used inside a definition after [ to go back to compiling.", "example": ": SIX [ 2 3 * ] LITERAL ;\n: SEVEN [ SIX 1+ ] LITERAL ;\nSEVEN .                  \\ expect: 7", "part": "03_language.md"},
};
